use glam::DVec3;use ingetrazo_core::{math::Ray,scene::SelectionItem};use ingetrazo_gui::IngeTrazoApp;use ingetrazo_tools::base::{ToolType,ToolContext};
fn context(x:f64,y:f64)->ToolContext{ToolContext::new(DVec3::new(x,y,0.),Ray::new(DVec3::new(x,y,10.),-DVec3::Z))}
#[test]
fn face_pick_perpendicular_preview_cancel_paint_partition_and_one_history(){
 let mut app=IngeTrazoApp::new();let ids=[DVec3::ZERO,DVec3::X*4.,DVec3::new(4.,4.,0.),DVec3::Y*4.].map(|p|app.scene.mesh.add_vertex(p));app.scene.mesh.add_face(ids.to_vec(),vec![]);let attrs=serde_json::json!({"color":[0.2,0.4,0.6,1.],"mat":"Paint","texture":{"uvw":[1.,0.,0.,3.,0.,2.,0.,4.],"vendor_projection":71},"vendor_paint":17});app.scene.mesh.faces[0].attrs=serde_json::from_value(attrs).unwrap();app.set_tool(ToolType::Offset);let before=app.scene.clone();app.dispatch_tool_click(&context(1.,0.));app.active_tool.on_move(&mut app.scene,&context(3.,0.5));assert_eq!(app.scene,before);assert!(app.undo_stack.is_empty());let lines=app.active_tool.rubber_band_lines();assert_eq!(lines.len(),4);let mut points:Vec<_>=lines.iter().flat_map(|(a,b)|[*a,*b]).collect();points.sort_by(|a,b|a.x.total_cmp(&b.x).then(a.y.total_cmp(&b.y)));assert_eq!(points[0],DVec3::new(0.5,0.5,0.));assert_eq!(points.last().unwrap(),&DVec3::new(3.5,3.5,0.));app.active_tool.on_cancel(&mut app.scene);assert_eq!(app.scene,before);assert!(app.undo_stack.is_empty());
 app.dispatch_tool_click(&context(1.,0.));app.active_tool.on_move(&mut app.scene,&context(3.,0.5));app.dispatch_tool_vcb("0.5").unwrap();assert_eq!(app.undo_stack.len(),1);assert_eq!(app.scene.mesh.faces.len(),2);assert!((app.scene.mesh.faces.iter().enumerate().map(|(i,_)|app.scene.mesh.face_area(i)).sum::<f64>()-16.).abs()<1e-8);assert!(app.scene.mesh.faces.iter().all(|f|f.attrs==before.mesh.faces[0].attrs));assert!(app.scene.mesh.faces.iter().any(|f|f.holes.len()==1));let after=app.scene.clone();app.undo();assert_eq!(app.scene,before);app.redo();assert_eq!(app.scene,after);
 app.dispatch_tool_click(&context(1.,0.));let failure=app.scene.clone();let depth=app.undo_stack.len();assert!(app.dispatch_tool_vcb("NaN").is_err());assert_eq!(app.scene,failure);assert_eq!(app.undo_stack.len(),depth);
}
#[test]
fn selected_chain_typed_radius_preserves_dragged_sign_and_undo(){
 let mut app=IngeTrazoApp::new();let ids=[DVec3::ZERO,DVec3::X*4.,DVec3::new(4.,4.,0.)].map(|p|app.scene.mesh.add_vertex(p));for p in ids.windows(2){let id=app.scene.mesh.add_edge(p[0],p[1]).unwrap();app.scene.select(SelectionItem::Edge(id));}app.set_tool(ToolType::Offset);let before=app.scene.clone();app.dispatch_tool_click(&context(2.,0.));app.active_tool.on_move(&mut app.scene,&context(3.,-0.25));assert_eq!(app.scene,before);app.dispatch_tool_vcb("0.5").unwrap();assert_eq!(app.undo_stack.len(),1);assert_eq!(app.scene.mesh.edges.len(),4);for p in [DVec3::new(0.,-0.5,0.),DVec3::new(4.5,-0.5,0.),DVec3::new(4.5,4.,0.)]{assert!(app.scene.mesh.vertices.iter().any(|v|v.position.distance(p)<1e-8));}app.undo();assert_eq!(app.scene,before);
}
